begin;

-- Catálogos are private, organization-owned documents. The database stores
-- immutable object paths only; signed URLs are generated by clients when needed.
do $$
begin
  if to_regprocedure('public.current_organization_id()') is null
     or to_regprocedure('public.require_current_organization_id()') is null then
    raise exception 'catalogs require the existing organization helpers';
  end if;
end;
$$;

insert into storage.buckets (
  id,
  name,
  public,
  file_size_limit,
  allowed_mime_types
)
values (
  'catalogos',
  'catalogos',
  false,
  104857600,
  array['application/pdf', 'image/webp', 'image/jpeg', 'image/png']::text[]
)
on conflict (id) do update set
  name = excluded.name,
  public = false,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

create table if not exists public.catalogos (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null
    references public.organizations(id) on delete restrict,
  titulo text not null,
  archivo_path text,
  portada_path text,
  version integer not null default 1,
  numero_paginas integer,
  estado text not null default 'borrador',
  activo boolean not null default true,
  destacado boolean not null default false,
  orden integer not null default 0,
  fecha_publicacion timestamptz,
  fecha_actualizacion timestamptz,
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  constraint catalogos_titulo_valid check (
    length(trim(titulo)) between 1 and 200
  ),
  constraint catalogos_version_valid check (version >= 1),
  constraint catalogos_numero_paginas_valid check (
    numero_paginas is null or numero_paginas >= 1
  ),
  constraint catalogos_estado_valid check (
    estado in ('borrador', 'publicado')
  ),
  constraint catalogos_orden_valid check (orden >= 0),
  constraint catalogos_paths_together check (
    (archivo_path is null) = (portada_path is null)
  ),
  constraint catalogos_archivo_path_valid check (
    archivo_path is null or archivo_path =
      organization_id::text || '/' || id::text || '/v' || version::text ||
      '/catalogo.pdf'
  ),
  constraint catalogos_portada_path_valid check (
    portada_path is null or portada_path =
      organization_id::text || '/' || id::text || '/v' || version::text ||
      '/portada.webp'
  ),
  constraint catalogos_publication_valid check (
    (
      estado = 'borrador'
      and archivo_path is null
      and portada_path is null
      and numero_paginas is null
      and fecha_publicacion is null
      and fecha_actualizacion is null
    )
    or
    (
      estado = 'publicado'
      and archivo_path is not null
      and portada_path is not null
      and numero_paginas is not null
      and fecha_publicacion is not null
      and fecha_actualizacion is not null
      and fecha_actualizacion >= fecha_publicacion
    )
  ),
  constraint catalogos_destacado_valid check (
    not destacado or (estado = 'publicado' and activo)
  )
);

create unique index if not exists catalogos_org_titulo_normalizado_key
  on public.catalogos (
    organization_id,
    lower(regexp_replace(trim(titulo), '\s+', ' ', 'g'))
  );

create index if not exists catalogos_listado_idx
  on public.catalogos (
    organization_id,
    estado,
    activo,
    destacado desc,
    orden,
    fecha_actualizacion desc nulls last
  );

create index if not exists catalogos_busqueda_titulo_idx
  on public.catalogos (organization_id, lower(titulo) text_pattern_ops);

create unique index if not exists catalogos_one_active_featured_per_org
  on public.catalogos (organization_id)
  where estado = 'publicado' and activo and destacado;

create or replace view public.catalogos_con_etiquetas
with (security_invoker = true)
as
select
  c.*,
  (
    c.estado = 'publicado'
    and c.version = 1
    and c.fecha_publicacion >= current_timestamp - interval '14 days'
  ) as es_nuevo,
  (
    c.estado = 'publicado'
    and c.version > 1
    and c.fecha_actualizacion >= current_timestamp - interval '14 days'
  ) as es_actualizado
from public.catalogos c;

create or replace function public.set_catalogos_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := clock_timestamp();
  return new;
end;
$$;

drop trigger if exists catalogos_set_updated_at on public.catalogos;
create trigger catalogos_set_updated_at
before update on public.catalogos
for each row execute function public.set_catalogos_updated_at();

create or replace function public.is_current_organization_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.organization_members m
    join public.organizations o on o.id = m.organization_id
    where m.user_id = auth.uid()
      and m.organization_id = public.current_organization_id()
      and m.active
      and m.role = 'admin'
      and o.active
  );
$$;

create or replace function public.is_valid_catalog_storage_path(
  p_name text,
  p_organization_id uuid
)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select p_name ~ (
    '^' || p_organization_id::text ||
    '/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}' ||
    '/v[1-9][0-9]*/(catalogo[.]pdf|portada[.]webp)$'
  );
$$;

alter table public.catalogos enable row level security;

drop policy if exists "members read published active catalogs" on public.catalogos;
create policy "members read published active catalogs"
on public.catalogos
for select
to authenticated
using (
  organization_id = public.current_organization_id()
  and (
    (estado = 'publicado' and activo)
    or public.is_current_organization_admin()
  )
);

drop policy if exists "admins insert organization catalogs" on public.catalogos;
create policy "admins insert organization catalogs"
on public.catalogos
for insert
to authenticated
with check (
  organization_id = public.current_organization_id()
  and public.is_current_organization_admin()
);

drop policy if exists "admins update organization catalogs" on public.catalogos;
create policy "admins update organization catalogs"
on public.catalogos
for update
to authenticated
using (
  organization_id = public.current_organization_id()
  and public.is_current_organization_admin()
)
with check (
  organization_id = public.current_organization_id()
  and public.is_current_organization_admin()
);

drop policy if exists "admins delete organization catalogs" on public.catalogos;
create policy "admins delete organization catalogs"
on public.catalogos
for delete
to authenticated
using (
  organization_id = public.current_organization_id()
  and public.is_current_organization_admin()
);

drop policy if exists "members read organization catalog objects" on storage.objects;
create policy "members read organization catalog objects"
on storage.objects
for select
to authenticated
using (
  bucket_id = 'catalogos'
  and public.is_valid_catalog_storage_path(
    name,
    public.current_organization_id()
  )
  and (
    public.is_current_organization_admin()
    or exists (
      select 1
      from public.catalogos c
      where c.organization_id = public.current_organization_id()
        and c.estado = 'publicado'
        and c.activo
        and (c.archivo_path = name or c.portada_path = name)
    )
  )
);

drop policy if exists "admins upload organization catalog objects" on storage.objects;
create policy "admins upload organization catalog objects"
on storage.objects
for insert
to authenticated
with check (
  bucket_id = 'catalogos'
  and public.is_current_organization_admin()
  and public.is_valid_catalog_storage_path(
    name,
    public.current_organization_id()
  )
);

drop policy if exists "admins update organization catalog objects" on storage.objects;
-- No UPDATE policy is intentional: published object paths are immutable.
-- Replacements use INSERT at v{version + 1}, followed by API deletion of the
-- previous version after the metadata transaction succeeds.

drop policy if exists "admins delete organization catalog objects" on storage.objects;
create policy "admins delete organization catalog objects"
on storage.objects
for delete
to authenticated
using (
  bucket_id = 'catalogos'
  and public.is_current_organization_admin()
  and public.is_valid_catalog_storage_path(
    name,
    public.current_organization_id()
  )
);

create or replace function public.admin_create_catalog_draft(
  p_titulo text,
  p_orden integer default 0
)
returns table (
  catalogo_id uuid,
  version_actual integer,
  archivo_path_esperado text,
  portada_path_esperada text
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  org uuid := public.require_current_organization_id();
  new_id uuid := gen_random_uuid();
  clean_title text := trim(regexp_replace(coalesce(p_titulo, ''), '\s+', ' ', 'g'));
begin
  if not public.is_current_organization_admin() then
    raise exception 'organization administrator required' using errcode = '42501';
  end if;
  if length(clean_title) not between 1 and 200 then
    raise exception 'catalog title must contain between 1 and 200 characters'
      using errcode = '22023';
  end if;
  if p_orden is null or p_orden < 0 then
    raise exception 'catalog order must be zero or greater' using errcode = '22023';
  end if;

  insert into public.catalogos (
    id,
    organization_id,
    titulo,
    version,
    estado,
    activo,
    destacado,
    orden
  )
  values (
    new_id,
    org,
    clean_title,
    1,
    'borrador',
    true,
    false,
    p_orden
  );

  return query select
    new_id,
    1,
    org::text || '/' || new_id::text || '/v1/catalogo.pdf',
    org::text || '/' || new_id::text || '/v1/portada.webp';
end;
$$;

create or replace function public.admin_publish_catalog(
  p_catalogo_id uuid,
  p_titulo text,
  p_archivo_path text,
  p_portada_path text,
  p_numero_paginas integer,
  p_reemplazar_archivo boolean default false,
  p_orden integer default null
)
returns public.catalogos
language plpgsql
security definer
set search_path = ''
as $$
declare
  org uuid := public.require_current_organization_id();
  catalog_row public.catalogos%rowtype;
  result_catalog public.catalogos%rowtype;
  clean_title text := trim(regexp_replace(coalesce(p_titulo, ''), '\s+', ' ', 'g'));
  next_version integer;
  expected_file text;
  expected_cover text;
  published_at timestamptz := clock_timestamp();
begin
  if not public.is_current_organization_admin() then
    raise exception 'organization administrator required' using errcode = '42501';
  end if;
  if p_reemplazar_archivo is null then
    raise exception 'p_reemplazar_archivo is required' using errcode = '22023';
  end if;
  if length(clean_title) not between 1 and 200 then
    raise exception 'catalog title must contain between 1 and 200 characters'
      using errcode = '22023';
  end if;
  if p_orden is not null and p_orden < 0 then
    raise exception 'catalog order must be zero or greater' using errcode = '22023';
  end if;

  select c.* into catalog_row
  from public.catalogos c
  where c.id = p_catalogo_id and c.organization_id = org
  for update;
  if not found then
    raise exception 'catalog not found' using errcode = 'P0002';
  end if;

  if catalog_row.estado = 'borrador' then
    if p_reemplazar_archivo then
      raise exception 'a draft is published at its current version'
        using errcode = '22023';
    end if;
    if p_archivo_path is null
       and p_portada_path is null
       and p_numero_paginas is null then
      update public.catalogos c set
        titulo = clean_title,
        orden = coalesce(p_orden, c.orden)
      where c.id = catalog_row.id
      returning c.* into result_catalog;
      return result_catalog;
    end if;
    next_version := catalog_row.version;
  elsif p_reemplazar_archivo then
    next_version := catalog_row.version + 1;
  else
    if p_archivo_path is not null
       or p_portada_path is not null
       or p_numero_paginas is not null then
      raise exception 'file metadata requires p_reemplazar_archivo = true'
        using errcode = '22023';
    end if;

    update public.catalogos c set
      titulo = clean_title,
      orden = coalesce(p_orden, c.orden)
    where c.id = catalog_row.id
    returning c.* into result_catalog;
    return result_catalog;
  end if;

  if p_numero_paginas is null or p_numero_paginas < 1 then
    raise exception 'published catalogs require a positive page count'
      using errcode = '22023';
  end if;
  expected_file := org::text || '/' || catalog_row.id::text ||
    '/v' || next_version::text || '/catalogo.pdf';
  expected_cover := org::text || '/' || catalog_row.id::text ||
    '/v' || next_version::text || '/portada.webp';
  if p_archivo_path is distinct from expected_file
     or p_portada_path is distinct from expected_cover then
    raise exception 'catalog object paths do not match the expected immutable version paths'
      using errcode = '22023';
  end if;

  update public.catalogos c set
    titulo = clean_title,
    archivo_path = expected_file,
    portada_path = expected_cover,
    version = next_version,
    numero_paginas = p_numero_paginas,
    estado = 'publicado',
    orden = coalesce(p_orden, c.orden),
    fecha_publicacion = coalesce(c.fecha_publicacion, published_at),
    fecha_actualizacion = published_at
  where c.id = catalog_row.id
  returning c.* into result_catalog;
  return result_catalog;
end;
$$;

create or replace function public.admin_set_featured_catalog(
  p_catalogo_id uuid
)
returns public.catalogos
language plpgsql
security definer
set search_path = ''
as $$
declare
  org uuid := public.require_current_organization_id();
  target public.catalogos%rowtype;
begin
  if not public.is_current_organization_admin() then
    raise exception 'organization administrator required' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(org::text, 8192));

  select c.* into target
  from public.catalogos c
  where c.id = p_catalogo_id and c.organization_id = org
  for update;
  if not found then
    raise exception 'catalog not found' using errcode = 'P0002';
  end if;
  if target.estado <> 'publicado' or not target.activo then
    raise exception 'only an active published catalog can be featured'
      using errcode = '22023';
  end if;

  update public.catalogos c
  set destacado = false
  where c.organization_id = org
    and c.destacado
    and c.id <> target.id;

  update public.catalogos c
  set destacado = true
  where c.id = target.id
  returning c.* into target;
  return target;
end;
$$;

create or replace function public.admin_set_catalog_active(
  p_catalogo_id uuid,
  p_activo boolean
)
returns public.catalogos
language plpgsql
security definer
set search_path = ''
as $$
declare
  org uuid := public.require_current_organization_id();
  result_catalog public.catalogos%rowtype;
begin
  if not public.is_current_organization_admin() then
    raise exception 'organization administrator required' using errcode = '42501';
  end if;
  if p_activo is null then
    raise exception 'active state is required' using errcode = '22023';
  end if;

  update public.catalogos c set
    activo = p_activo,
    destacado = case when p_activo then c.destacado else false end
  where c.id = p_catalogo_id and c.organization_id = org
  returning c.* into result_catalog;
  if not found then
    raise exception 'catalog not found' using errcode = 'P0002';
  end if;
  return result_catalog;
end;
$$;

create or replace function public.admin_delete_catalog_after_storage_cleanup(
  p_catalogo_id uuid,
  p_expected_version integer,
  p_storage_objects_deleted boolean
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  org uuid := public.require_current_organization_id();
  target public.catalogos%rowtype;
begin
  if not public.is_current_organization_admin() then
    raise exception 'organization administrator required' using errcode = '42501';
  end if;
  if p_storage_objects_deleted is distinct from true then
    raise exception 'storage object deletion must be confirmed before deleting metadata'
      using errcode = '22023';
  end if;

  select c.* into target
  from public.catalogos c
  where c.id = p_catalogo_id and c.organization_id = org
  for update;
  if not found then
    raise exception 'catalog not found' using errcode = 'P0002';
  end if;
  if p_expected_version is distinct from target.version then
    raise exception 'catalog version changed during storage cleanup'
      using errcode = '40001';
  end if;

  delete from public.catalogos c
  where c.id = target.id and c.organization_id = org;
  return true;
end;
$$;

revoke all on public.catalogos from public, anon, authenticated;
grant select on public.catalogos to authenticated;
grant select, insert, update, delete on public.catalogos to service_role;
revoke all on public.catalogos_con_etiquetas from public, anon, authenticated;
grant select on public.catalogos_con_etiquetas to authenticated;

revoke all on function public.set_catalogos_updated_at() from public, anon, authenticated;
revoke all on function public.is_current_organization_admin() from public, anon;
revoke all on function public.is_valid_catalog_storage_path(text, uuid) from public, anon;
revoke all on function public.admin_create_catalog_draft(text, integer) from public, anon;
revoke all on function public.admin_publish_catalog(
  uuid, text, text, text, integer, boolean, integer
) from public, anon;
revoke all on function public.admin_set_featured_catalog(uuid) from public, anon;
revoke all on function public.admin_set_catalog_active(uuid, boolean) from public, anon;
revoke all on function public.admin_delete_catalog_after_storage_cleanup(
  uuid, integer, boolean
) from public, anon;

grant execute on function public.is_current_organization_admin()
  to authenticated, service_role;
grant execute on function public.is_valid_catalog_storage_path(text, uuid)
  to authenticated, service_role;
grant execute on function public.admin_create_catalog_draft(text, integer)
  to authenticated;
grant execute on function public.admin_publish_catalog(
  uuid, text, text, text, integer, boolean, integer
) to authenticated;
grant execute on function public.admin_set_featured_catalog(uuid)
  to authenticated;
grant execute on function public.admin_set_catalog_active(uuid, boolean)
  to authenticated;
grant execute on function public.admin_delete_catalog_after_storage_cleanup(
  uuid, integer, boolean
) to authenticated;

-- Deployment-time structural verification. Any mismatch aborts the migration.
do $$
declare
  catalog_policy_count integer;
  object_policy_count integer;
begin
  if not exists (
    select 1 from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relname = 'catalogos' and c.relrowsecurity
  ) then
    raise exception 'catalogos RLS verification failed';
  end if;

  if not exists (
    select 1 from storage.buckets b
    where b.id = 'catalogos'
      and not b.public
      and b.file_size_limit = 104857600
      and b.allowed_mime_types @> array[
        'application/pdf', 'image/webp', 'image/jpeg', 'image/png'
      ]::text[]
      and cardinality(b.allowed_mime_types) = 4
  ) then
    raise exception 'catalogos bucket verification failed';
  end if;

  select count(*) into catalog_policy_count
  from pg_policies
  where schemaname = 'public'
    and tablename = 'catalogos'
    and policyname in (
      'members read published active catalogs',
      'admins insert organization catalogs',
      'admins update organization catalogs',
      'admins delete organization catalogs'
    )
    and roles = array['authenticated']::name[];
  if catalog_policy_count <> 4 then
    raise exception 'catalogos policy verification failed';
  end if;

  select count(*) into object_policy_count
  from pg_policies
  where schemaname = 'storage'
    and tablename = 'objects'
    and policyname in (
      'members read organization catalog objects',
      'admins upload organization catalog objects',
      'admins delete organization catalog objects'
    )
    and roles = array['authenticated']::name[];
  if object_policy_count <> 3 then
    raise exception 'catalog storage policy verification failed';
  end if;

  if not exists (
    select 1 from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relname = 'catalogos_con_etiquetas'
      and c.relkind = 'v'
  ) then
    raise exception 'catalog label view verification failed';
  end if;

  if to_regprocedure('public.admin_create_catalog_draft(text,integer)') is null
     or to_regprocedure(
       'public.admin_publish_catalog(uuid,text,text,text,integer,boolean,integer)'
     ) is null
     or to_regprocedure('public.admin_set_featured_catalog(uuid)') is null
     or to_regprocedure('public.admin_set_catalog_active(uuid,boolean)') is null
     or to_regprocedure(
       'public.admin_delete_catalog_after_storage_cleanup(uuid,integer,boolean)'
     ) is null then
    raise exception 'catalog RPC verification failed';
  end if;
end;
$$;

notify pgrst, 'reload schema';

commit;
